internal final class IntegrationClaimCheckScheduleService_INT extends SysOperationServiceBase
{


}

Method.Source:
public void process(IntegrationClaimCheckScheduleDC_INT _contract)
{

    Integration_INT integration;
    Query q = _contract.getQuery();

    QueryRun qr = new QueryRun(q);


    while(qr.next())
    {

        IntegrationSetupOutQueueTopics_INT topicToProcess = qr.get(tableNum(IntegrationSetupOutQueueTopics_INT));

        IntegrationSetup_Int integrationSetup = IntegrationSetup_Int::find(topicToProcess.IntegrationName);

        if (integrationSetup)
        {
            integration = IntegrationSetup_INT::createInstanceOfIntegrationClass(integrationSetup);

            DictClass dataContract = new DictClass(integration.DataContractIdentifier());

            IntegrationClaimCheckDC_INT claimCheck =  dataContract.makeObject();

            claimCheck.parmServiceBusQueueTopic(topicToProcess.QueueTopic);

            str payload = FormJsonSerializer::serializeClass(claimCheck);

            integration = integrationSetup.createIntegration(curExt(),payload,'');

            IntegrationHandler_INT::HandleEvent(integration);

        }

    }
}
